import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, vec3, vec4, mix, smoothstep, float, positionLocal, uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DirectionalLight, AmbientLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#111117', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const figures = items.map((it) => (typeof it === 'string' ? it : it.text)).filter(Boolean);
  const fallback = [
    'CAL NA-01 BEAT 28800 VPH', 'POWER RESERVE 72H', 'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK', 'WAITLIST 1204', 'NEXT FITTING JUL 18'
  ];
  const figs = figures.length ? figures : fallback;

  const root = new Group();
  root.name = config.id || 'ticker-ribbon';

  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;

  // ---- lights (node-local) ----
  const ambient = new AmbientLight(new Color(colors.paper), 0.55);
  root.add(ambient);
  const key = new DirectionalLight(new Color(colors.paper), 1.1);
  key.position.set(-1.2, 2.0, 3.0);
  root.add(key);
  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(2.0, -1.0, -1.5);
  root.add(rim);

  // ---- backdrop stage plane (vertical gradient) ----
  const bgGeo = new PlaneGeometry(7.4, 6.0);
  const bgMat = new MeshBasicNodeMaterial();
  const cTop = vec3(...hexToRGB('#0b0b10'));
  const cMid = vec3(...hexToRGB(colors.surface || '#111117'));
  const bgUv = uv();
  const grad = mix(cTop, cMid, smoothstep(float(0.0), float(0.5), bgUv.y));
  bgMat.colorNode = mix(grad, cTop, smoothstep(float(0.5), float(1.0), bgUv.y));
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  root.add(bg);

  // ---- ribbon rail ----
  const railGeo = new PlaneGeometry(RIBBON_W, RIBBON_H);
  const railMat = new MeshStandardNodeMaterial();
  railMat.color = new Color(colors.surface || '#111117');
  railMat.roughness = 0.6;
  railMat.metalness = 0.2;
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  root.add(rail);

  // hairlines top/bottom
  const hairMat = new MeshBasicNodeMaterial();
  hairMat.colorNode = vec3(...hexToRGB('#23232b'));
  const hairTop = new Mesh(new PlaneGeometry(RIBBON_W, 0.006), hairMat);
  hairTop.position.set(0, RIBBON_H / 2 - 0.003, 0.005);
  const hairBot = new Mesh(new PlaneGeometry(RIBBON_W, 0.006), hairMat);
  hairBot.position.set(0, -RIBBON_H / 2 + 0.003, 0.005);
  root.add(hairTop, hairBot);

  // ---- scrolling content strip ----
  // Build one strip of text + accent ticks, then duplicate for seamless loop.
  const strip = new Group();
  const disposables = [];

  const GAP = 0.5;        // gap on both sides of a tick
  const TICK_W = 0.02;
  const TICK_H = 0.14;
  const CHAR_W = 0.075;   // approx width per glyph at fontSize used

  let cursor = 0;
  function addTick(x) {
    const tickGeo = new BoxGeometry(TICK_W, TICK_H, 0.01);
    const tickMat = new MeshStandardNodeMaterial();
    tickMat.color = new Color(colors.accent);
    tickMat.emissive = new Color(colors.accent);
    tickMat.emissiveIntensity = 1.5;
    tickMat.roughness = 0.5;
    tickMat.metalness = 0.2;
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(x, 0, 0.02);
    strip.add(tick);
    disposables.push(tickGeo, tickMat);
  }

  for (let i = 0; i < figs.length; i++) {
    const text = figs[i];
    const label = ctx.fontAtlas.createText(text, {
      fontSize: 13,
      color: colors.paper || '#e8ecf2',
      align: 'left',
      letterSpacingPx: 0.06
    });
    const approxW = text.length * CHAR_W;
    label.position.set(cursor, 0, 0.02);
    strip.add(label);
    cursor += approxW;

    // gap + tick + gap
    cursor += GAP;
    addTick(cursor);
    cursor += GAP;
  }

  const STRIP_LEN = cursor;

  // second copy for seamless loop
  const strip2 = strip.clone(true);
  strip2.position.x = STRIP_LEN;

  const scroller = new Group();
  scroller.add(strip, strip2);
  scroller.position.set(-RIBBON_W / 2, 0, 0);
  root.add(scroller);

  // ---- edge fade masks (0.6 units each side) ----
  const maskMat = (mirror) => {
    const m = new MeshBasicNodeMaterial();
    m.transparent = true;
    const c = vec3(...hexToRGB('#0b0b10'));
    const u = uv();
    // opaque at outer edge -> transparent inward
    const t = mirror ? u.x : float(1.0).sub(u.x);
    m.colorNode = c;
    m.opacityNode = smoothstep(float(0.0), float(1.0), t);
    return m;
  };
  const maskGeo = new PlaneGeometry(0.6, RIBBON_H + 0.02);
  const maskL = new Mesh(maskGeo, maskMat(true));
  maskL.position.set(-RIBBON_W / 2 + 0.3, 0, 0.06);
  const maskR = new Mesh(maskGeo, maskMat(false));
  maskR.position.set(RIBBON_W / 2 - 0.3, 0, 0.06);
  root.add(maskL, maskR);

  // ---- fly-through primitive ----
  const primHandles = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const p of primList) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const h = fn(scroller, p.params || {});
      if (h) primHandles.push(h);
    }
  }

  // constant velocity leftward scroll (0.4 u/s), seamless
  const speed = 0.4;
  const period = STRIP_LEN / speed;
  const scrollTl = gsap.timeline({ repeat: -1 });
  scrollTl.fromTo(
    strip, { x: 0 }, { x: -STRIP_LEN, duration: period, ease: 'none' }, 0
  );
  scrollTl.fromTo(
    strip2, { x: STRIP_LEN }, { x: 0, duration: period, ease: 'none' }, 0
  );

  // entrance settle
  const entrance = gsap.timeline();
  root.scale.setScalar(0.98);
  entrance.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' });

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    scrollTl.kill();
    entrance.kill();
    for (const h of primHandles) { try { h.cleanup?.(); } catch (e) {} }
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => m.dispose?.());
      }
    });
    for (const d of disposables) d.dispose?.();
  };

  return root;
}

function hexToRGB(hex) {
  const h = hex.replace('#', '').slice(0, 6);
  const n = parseInt(h, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}
